promql:
(
  rate(container_network_receive_bytes_total{job="kubelet"}[5m]) 
  > 2 * rate(container_network_transmit_bytes_total[5m])
) AND (
  (sum(rate(container_fs_reads_bytes_total[5m])) + sum(rate(container_fs_writes_bytes_total[5m]))) * 8 / 1024 > 200 # converting B/s to KB/s
) AND (
  sum by (pod)(node_disk_io_time_seconds_total{device="cni0", container!="tempo-query"})[5m] > 1e-8
)
